public async Task Handle(PaymentReceived msg, CancellationToken ct)
{
    await using var tx = await _db.Database.BeginTransactionAsync(ct);

    if (await _db.InboxMessages.AnyAsync(m => m.MessageId == msg.MessageId, ct))
        return; // duplikat - już przetworzone

    var order = await _db.Orders.SingleAsync(o => o.Id == msg.OrderId, ct);
    if (order.Status == OrderStatus.Pending)
        order.MarkPaid(msg.Amount);

    _db.InboxMessages.Add(new InboxMessage(msg.MessageId, DateTime.UtcNow));
    await _db.SaveChangesAsync(ct); // unikalny indeks na MessageId
    await tx.CommitAsync(ct);
}

