public sealed class OutboxInterceptor : SaveChangesInterceptor
{
    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData data, InterceptionResult<int> result, CancellationToken ct = default)
    {
        var db = data.Context!;
        var events = db.ChangeTracker.Entries<IHasDomainEvents>()
            .SelectMany(e => e.Entity.PopDomainEvents())
            .ToList();

        db.Set<OutboxMessage>().AddRange(events.Select(e => new OutboxMessage
        {
            Id = Guid.NewGuid(),
            Type = e.GetType().Name,
            Payload = JsonSerializer.Serialize(e, e.GetType()),
            OccurredAt = DateTime.UtcNow
        }));
        return base.SavingChangesAsync(data, result, ct);
    }
}

app.MapPost("/payments", async ([FromHeader(Name = "Idempotency-Key")] Guid key,
    PaymentRequest req, PaymentsDb db, IPaymentService payments, CancellationToken ct) =>
{
    var existing = await db.IdempotencyRecords.FindAsync([key], ct);
    if (existing is { Response: not null })
        return Results.Json(existing.Response, statusCode: existing.StatusCode);
    if (existing is not null)
        return Results.Conflict("Request in progress");

    db.IdempotencyRecords.Add(new IdempotencyRecord(key, req.Hash()));
    await db.SaveChangesAsync(ct); // unikalny klucz = ochrona przed wyścigiem

    var result = await payments.ChargeAsync(req, ct);
    await db.SaveResponseAsync(key, result, StatusCodes.Status201Created, ct);
    return Results.Created($"/payments/{result.Id}", result);
});

