public class ProductService(HybridCache cache, ShopDb db)
{
    public ValueTask<ProductDto?> GetAsync(int id, CancellationToken ct) =>
        cache.GetOrCreateAsync($"product:{id}",
            async token => await db.Products.Where(p => p.Id == id)
                .Select(p => new ProductDto(p.Id, p.Name, p.Price))
                .FirstOrDefaultAsync(token),
            tags: ["products"], cancellationToken: ct);

    public async Task UpdatedAsync(int id, CancellationToken ct) =>
        await cache.RemoveAsync($"product:{id}", ct);
}

